INSERT INTO public.lobby(master_id,room_name,host_id,players,player_limit,is_public,peak_players,peak_time,first_seen,last_seen,closed_at,date_created,date_updated) SELECT value.master_id,value.room_name,value.host_id,value.players,value.player_limit,value.is_public,value.players,$2::timestamptz,$2::timestamptz,$2::timestamptz,NULL,$2::timestamptz,$2::timestamptz FROM jsonb_to_recordset($1) AS value(master_id text,room_name text,host_id bigint,host_name text,players integer,player_limit integer,is_public boolean) ON CONFLICT(master_id) DO UPDATE SET room_name=excluded.room_name,host_id=excluded.host_id,players=excluded.players,player_limit=excluded.player_limit,is_public=excluded.is_public, peak_players=CASE WHEN excluded.players>lobby.peak_players THEN excluded.players ELSE lobby.peak_players END, peak_time=CASE WHEN excluded.players>lobby.peak_players THEN excluded.last_seen ELSE lobby.peak_time END, last_seen=excluded.last_seen,closed_at=NULL,date_updated=excluded.date_updated RETURNING id,master_id
